#!/usr/bin/env python3
"""Held-out Diagram voice set (heldout-voice.jsonl): hand-written requests, never generated by the frames and never part of the
official dataset (validate.py checks that no text occurs in examples.jsonl or the official dataset). It holds the owner's
example requests (prompt of 2026-11-20) verbatim and new paraphrases of every phenomenon: typos, voice transcripts, vague
requests, references (codes, populations, recency, the selection), compounds and questions. Run: python3 heldout.py"""
import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
from engine import Scene, assemble, parse  # noqa: E402


def scene(nodes, links=(), groups=()):
    s = Scene.empty()
    s.nodes = [{'code': f'n{i + 1}', 'kind': k, 'label': l} for i, (k, l) in enumerate(nodes)]
    s.links = [{'code': f'e{i + 1}', 'from': a, 'to': b} for i, (a, b) in enumerate(links)]
    s.groups = [{'code': f'g{i + 1}', 'label': l, 'members': m} for i, (l, m) in enumerate(groups)]
    return s


FLOW = scene([('circle', 'Start'), ('rectangle', 'Login'), ('diamond', 'Valid?'), ('rectangle', 'Dashboard'), ('circle', 'End'), ('rectangle', None)],
             [('n1', 'n2'), ('n2', 'n3'), ('n3', 'n4'), ('n4', 'n5')], [('Auth', ['n2', 'n3'])])
SHAPES = scene([('circle', None), ('circle', None), ('rectangle', None), ('rectangle', None), ('rectangle', None), ('diamond', None)], [('n1', 'n3')])
EMPTY = scene([])
