def main():
    out = []
    for i, (markup, attrs, sc, phen) in enumerate(ITEMS, 1):
        segs, n = parse(markup)
        text, reqs = assemble(segs, n, attrs)
        out.append({'format': 'psys2.ui-diagram-example/2', 'id': f'ui-diagram-v2-heldout-{i:04d}', 'world': 'diagram', 'text': text,
                    'context': {'existing': sc.existing(), 'previous': None}, 'requests': reqs, 'style': 'heldout-' + phen, 'tier': 'heldout',
                    'phase': 'direct', 'cohort': {'operation': attrs[0]['op'] if len(attrs) == 1 else 'compound', 'case': 'heldout:' + phen,
                                                  'recipeFamily': f'heldout:{i}'},
                    'nativeTool': None, 'provenance': 'C1: hand-written held-out voice request (heldout.py); never in training'})
    (HERE / 'heldout-voice.jsonl').write_text(''.join(json.dumps(r, ensure_ascii=False) + '\n' for r in out))
    print(json.dumps({'rows': len(out)}))


if __name__ == '__main__':
    main()
